CREATE TABLE schema_versions (version int PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, tax_number text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid REFERENCES businesses, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','OWNER','COUNTER','AUDITOR','GUEST')), permissions text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'INVITED' CHECK(status IN ('INVITED','VERIFIED','PENDING_APPROVAL','ACTIVE','REJECTED')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(role <> 'OWNER' OR business_id IS NOT NULL));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, token_hash text NOT NULL UNIQUE, otp_hash text NOT NULL, attempts int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, verified_at timestamptz, consumed_at timestamptz);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users, filename text NOT NULL, original_name text NOT NULL, mime_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, name text NOT NULL, address text NOT NULL DEFAULT '', UNIQUE(business_id,name));
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), warehouse_id uuid NOT NULL REFERENCES warehouses, parent_id uuid REFERENCES locations, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('ZONE','RACK','FLOOR','BIN','BUFFER','QUARANTINE')), code text NOT NULL UNIQUE DEFAULT ('LOC-' || upper(substr(gen_random_uuid()::text,1,8))));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, sku text NOT NULL, barcode text NOT NULL, name text NOT NULL, category text NOT NULL DEFAULT '', subcategory text NOT NULL DEFAULT '', brand text NOT NULL DEFAULT '', model text NOT NULL DEFAULT '', variant text NOT NULL DEFAULT '', purchase_price numeric(14,2) NOT NULL DEFAULT 0 CHECK(purchase_price>=0), sale_price numeric(14,2) NOT NULL DEFAULT 0 CHECK(sale_price>=0), vat numeric(5,2) NOT NULL DEFAULT 20 CHECK(vat BETWEEN 0 AND 100), supplier text NOT NULL DEFAULT '', min_stock numeric(14,3) NOT NULL DEFAULT 0 CHECK(min_stock>=0), max_stock numeric(14,3) NOT NULL DEFAULT 0 CHECK(max_stock>=min_stock), abc text NOT NULL DEFAULT 'C' CHECK(abc IN ('A','B','C')), UNIQUE(business_id,sku), UNIQUE(business_id,barcode));
CREATE TABLE product_units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products, name text NOT NULL, multiplier numeric(14,3) NOT NULL CHECK(multiplier>0), UNIQUE(product_id,name));
CREATE TABLE stocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products, location_id uuid NOT NULL REFERENCES locations, physical numeric(14,3) NOT NULL DEFAULT 0 CHECK(physical>=0), reserved numeric(14,3) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=physical), damaged numeric(14,3) NOT NULL DEFAULT 0 CHECK(damaged>=0), returned numeric(14,3) NOT NULL DEFAULT 0 CHECK(returned>=0), lot text NOT NULL DEFAULT '', serial text NOT NULL DEFAULT '', last_count_at timestamptz, UNIQUE(product_id,location_id,lot,serial));
CREATE TABLE rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_id uuid NOT NULL REFERENCES businesses, warehouse_id uuid NOT NULL REFERENCES warehouses, name text NOT NULL, code text NOT NULL UNIQUE DEFAULT ('BEDSS-' || upper(substr(gen_random_uuid()::text,1,8))), count_type text NOT NULL CHECK(count_type IN ('FULL','PARTIAL','CYCLIC','RACK')), method text NOT NULL CHECK(method IN ('INTERNAL','AUDITOR','HYBRID')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','OPEN','COMPLETED','APPROVED','REJECTED')), created_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE TABLE room_items (room_id uuid NOT NULL REFERENCES rooms, stock_id uuid NOT NULL REFERENCES stocks, expected numeric(14,3) NOT NULL, unit_cost numeric(14,2) NOT NULL, PRIMARY KEY(room_id,stock_id));
CREATE TABLE assignments (room_id uuid NOT NULL REFERENCES rooms, user_id uuid NOT NULL REFERENCES users, location_id uuid NOT NULL REFERENCES locations, approved boolean NOT NULL DEFAULT false, joined_at timestamptz, finished_at timestamptz, PRIMARY KEY(room_id,user_id,location_id));
CREATE TABLE active_locations (user_id uuid PRIMARY KEY REFERENCES users, room_id uuid NOT NULL REFERENCES rooms, location_id uuid NOT NULL REFERENCES locations, activated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE count_locks (stock_id uuid PRIMARY KEY REFERENCES stocks, room_id uuid NOT NULL REFERENCES rooms, user_id uuid NOT NULL UNIQUE REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE count_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL, stock_id uuid NOT NULL, user_id uuid NOT NULL REFERENCES users, quantity numeric(14,3) NOT NULL CHECK(quantity>=0), unit text NOT NULL, base_quantity numeric(14,3) NOT NULL CHECK(base_quantity>=0), condition text NOT NULL CHECK(condition IN ('NORMAL','DAMAGED','RETURNED','DISPLAY','BROKEN')), note text NOT NULL DEFAULT '', photo_id uuid REFERENCES documents, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(room_id,stock_id), FOREIGN KEY(room_id,stock_id) REFERENCES room_items);
CREATE TABLE incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES rooms, user_id uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('BREAK','DAMAGE','ACCIDENT')), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, business_id uuid REFERENCES businesses, actor_id uuid REFERENCES users, action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_business_date ON audit_logs(business_id,created_at DESC);
CREATE INDEX room_business ON rooms(business_id);
CREATE INDEX assignment_user ON assignments(user_id,room_id);
CREATE INDEX stock_location ON stocks(location_id);
INSERT INTO schema_versions(version) VALUES(1);
